const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = readInt();
    if (N === null) return;
    const B = readInt();

    // Arestas: cada aresta tem u, v, w
    // Usaremos typed arrays para ordenar eficientemente
    const edgeU = new Int32Array(B);
    const edgeV = new Int32Array(B);
    const edgeW = new Int32Array(B);
    const edgeIdx = new Int32Array(B);

    for (let i = 0; i < B; i++) {
        edgeU[i] = readInt();
        edgeV[i] = readInt();
        edgeW[i] = readInt();
        edgeIdx[i] = i;
    }

    // Ordenação decrescente por peso
    // Como pesos P <= 10^5, podemos usar Counting Sort / Radix Sort para ser muito rápido,
    // ou simplesmente sort com typed array
    edgeIdx.sort((a, b) => edgeW[b] - edgeW[a]);

    // DSU para Kruskal
    const parent = new Int32Array(N + 1);
    for (let i = 1; i <= N; i++) parent[i] = i;

    function find(i) {
        let root = i;
        while (root !== parent[root]) {
            root = parent[root];
        }
        let curr = i;
        while (curr !== root) {
            let nxt = parent[curr];
            parent[curr] = root;
            curr = nxt;
        }
        return root;
    }

    // Lista de adjacência da MST usando Forward Star (formato CSR)
    // MST tem N-1 arestas => 2 * (N - 1) direcionadas
    const head = new Int32Array(N + 1).fill(-1);
    const to = new Int32Array(2 * N);
    const weight = new Int32Array(2 * N);
    const nextEdge = new Int32Array(2 * N);
    let edgeCount = 0;

    function addTreeEdge(u, v, w) {
        to[edgeCount] = v;
        weight[edgeCount] = w;
        nextEdge[edgeCount] = head[u];
        head[u] = edgeCount++;

        to[edgeCount] = u;
        weight[edgeCount] = w;
        nextEdge[edgeCount] = head[v];
        head[v] = edgeCount++;
    }

    let edgesAdded = 0;
    for (let i = 0; i < B; i++) {
        const id = edgeIdx[i];
        const u = edgeU[id];
        const v = edgeV[id];
        const w = edgeW[id];

        const rootU = find(u);
        const rootV = find(v);
        if (rootU !== rootV) {
            parent[rootU] = rootV;
            addTreeEdge(u, v, w);
            edgesAdded++;
            if (edgesAdded === N - 1) break;
        }
    }

    // Binary Lifting
    const LOGN = 18;
    const up = new Int32Array(LOGN * (N + 1));
    const minEdge = new Int32Array(LOGN * (N + 1));
    const depth = new Int32Array(N + 1);
    const visited = new Uint8Array(N + 1);

    // BFS para enraizar a árvore no nó 1
    const queue = new Int32Array(N + 1);
    let qHead = 0, qTail = 0;

    queue[qTail++] = 1;
    visited[1] = 1;
    depth[1] = 0;
    up[0 * (N + 1) + 1] = 1;
    minEdge[0 * (N + 1) + 1] = 1e9;

    while (qHead < qTail) {
        const u = queue[qHead++];
        for (let e = head[u]; e !== -1; e = nextEdge[e]) {
            const v = to[e];
            const w = weight[e];
            if (!visited[v]) {
                visited[v] = 1;
                depth[v] = depth[u] + 1;
                up[0 * (N + 1) + v] = u;
                minEdge[0 * (N + 1) + v] = w;
                queue[qTail++] = v;
            }
        }
    }

    // Preenche tabela de binary lifting
    for (let k = 1; k < LOGN; k++) {
        const prevOffset = (k - 1) * (N + 1);
        const currOffset = k * (N + 1);
        for (let i = 1; i <= N; i++) {
            const p = up[prevOffset + i];
            up[currOffset + i] = up[prevOffset + p];
            const m1 = minEdge[prevOffset + i];
            const m2 = minEdge[prevOffset + p];
            minEdge[currOffset + i] = m1 < m2 ? m1 : m2;
        }
    }

    function query(u, v) {
        let ans = 1e9;
        if (depth[u] < depth[v]) {
            let temp = u; u = v; v = temp;
        }

        // Sobe u até depth[u] == depth[v]
        for (let k = LOGN - 1; k >= 0; k--) {
            if (depth[u] - (1 << k) >= depth[v]) {
                const w = minEdge[k * (N + 1) + u];
                if (w < ans) ans = w;
                u = up[k * (N + 1) + u];
            }
        }

        if (u === v) return ans;

        for (let k = LOGN - 1; k >= 0; k--) {
            const upU = up[k * (N + 1) + u];
            const upV = up[k * (N + 1) + v];
            if (upU !== upV) {
                const wU = minEdge[k * (N + 1) + u];
                const wV = minEdge[k * (N + 1) + v];
                if (wU < ans) ans = wU;
                if (wV < ans) ans = wV;
                u = upU;
                v = upV;
            }
        }

        const wU = minEdge[0 * (N + 1) + u];
        const wV = minEdge[0 * (N + 1) + v];
        if (wU < ans) ans = wU;
        if (wV < ans) ans = wV;

        return ans;
    }

    const C = readInt();
    let out = '';
    for (let i = 0; i < C; i++) {
        const X = readInt();
        const Y = readInt();
        out += query(X, Y) + '\n';
        if (out.length > 65536) {
            process.stdout.write(out);
            out = '';
        }
    }
    if (out.length > 0) {
        process.stdout.write(out);
    }
}

